-- Merge workflow-local input definitions without replacing IDs or custom settings.
-- Exact replays make no writes. New variables append after existing/custom order.
DO $workflow_variable_seed$
DECLARE
    seed_row RECORD;
    existing_row application.workflow_stage_variable%ROWTYPE;
    next_order INTEGER;
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('application.workflow_stage_variable.reference_seed', 0)
    );
