    ('logical', 'tool_assisted', 'build_authoring', 'neighbor_entities', 'workflow.logical.common.build_authoring.inputs.neighbor_entities', 'json', 'Active Entities just outside this area: parents or children of existing_entities, or built from tables that Analysis links to this area''s tables. Use them as Relationship parents by schema and name; change one only when this area''s evidence requires it.', '[{"schema":"silver","name":"Customer","type":"core","grain":"One row per customer_id.","natural_keys":[{"name":"SourceCustomerNumber","type":"BIGINT"}],"linked_via":["relationship"]}]'::jsonb, 110),
