    ('validation', NULL, 'validation_generation', 'mapping_evidence', 'workflow.validation.common.validation_generation.inputs.mapping_evidence', 'json', 'Relevant applied modeled target identities with natural-key Code-style target/source metadata and exact applied Object/Attribute transformations. Context is design evidence, not measured outcomes. A null transformation means this System has no saved rule there; leave it unchecked.', '[{"modeled_entity_type":"logical_entity","modeled_entity_name":"Customer","context":{"target_metadata":{"tenant_code":"NWA","tenant_catalog":"northwind","system_code":"GDS","connection_code":"lakehouse","object_schema":"silver_crm","object_name":"Customer","object_description":null,"zone_code":"silver","source_tenant_code":"NWA","source_tenant_name":"Northwind","tenant_name":"Shared warehouse","system_name":"Warehouse","attributes":[{"attribute_data_type":"BIGINT","attribute_description":null,"attribute_inferred_data_type":null,"attribute_name":"CustomerID","attribute_nullability":false,"attribute_ordinal_position":1,"is_active":true,"is_locked":false}],"modeled_entity_type":"logical_entity","modeled_entity_schema_name":"silver_crm","modeled_entity_name":"Customer"},"source_metadata":[{"role":"primary","rationale":"Recorded customer source.","is_locked":false,"object":{"tenant_code":"NWA","tenant_catalog":"northwind","system_code":"CRM","connection_code":"crm_bronze","object_schema":"bronze_crm","object_name":"customer","object_description":null,"zone_code":"bronze","is_active":true,"is_locked":false,"scope_is_active":true,"scope_is_locked":false,"attributes":[{"attribute_data_type":"BIGINT","attribute_description":null,"attribute_inferred_data_type":null,"attribute_name":"customer_id","attribute_nullability":false,"attribute_ordinal_position":1,"is_active":true,"is_locked":false}]},"source_system_code":"CRM"}],"source_systems":[{"system_code":"CRM","system_name":"CRM"}],"object_transformations":[{"object_dependency_order":10,"entity":{"entity_type":"logical_entity","entity_name":"Customer","definition":"Customer identity.","classification":"entity","grain":null,"entity_schema_name":"silver"},"transformation":{"steps":[{"name":"customers","source":"customer_source"}]},"source_system_code":"CRM"}],"attribute_transformations":[{"target_attribute_name":"CustomerID","target_attribute_ordinal_position":1,"transformation":{"expression":"CAST(customer_id AS BIGINT)"},"source_system_code":"CRM","modeled_entity_type":"logical_entity","modeled_entity_name":"Customer","modeled_entity_schema_name":"silver"}]},"modeled_entity_schema_name":"silver"}]'::jsonb, 30),
    ('validation', NULL, 'validation_generation', 'current_code', 'workflow.validation.common.validation_generation.inputs.current_code', 'json', 'Current saved Code artifacts and contributing Source System codes, with lifecycle/locks, storage metadata and optional inline content. Git references do not supply source contents. Empty means unavailable; no execution success is implied.', '[{"modeled_entity_type":"logical_entity","modeled_entity_name":"Customer","artifact_name":"customer.sql","artifact_type":"sql_file","code_storage_type":"table","code_repository_url":null,"code_commit_path":null,"code_entry_point":null,"code_parameters":null,"generated_code_content":"SELECT customer_id FROM warehouse.bronze.customer;","generated_code_status":"active","generated_code_is_locked":false,"source_system_codes":["CRM"],"modeled_entity_schema_name":"silver"}]'::jsonb, 40),
    ('validation', NULL, 'validation_generation', 'applied_groups', 'workflow.validation.common.validation_generation.inputs.applied_groups', 'json', 'Existing Validation Group records, including lifecycle, locks and exact Tenant/System/Group natural identities.', '[{"is_locked":false,"tenant_code":"NWA","system_code":"CRM","validation_group_name":"customer_keys","validation_group_description":"Recorded customer key constraints.","is_active":true}]'::jsonb, 50),
    ('validation', NULL, 'validation_generation', 'applied_checks', 'workflow.validation.common.validation_generation.inputs.applied_checks', 'json', 'Existing Validation Check records, exact typed operator/operand definitions and SQL, lifecycle/locks and Tenant/System/Group/Check natural identities. These are definitions, not execution results.', '[{"is_locked":false,"tenant_code":"NWA","system_code":"CRM","validation_group_name":"customer_keys","validation_check_name":"customer_id_not_null","validation_check_description":null,"validation_category_code":"technical.nullability","validation_severity":"blocking","validation_query_sql":"SELECT count(*) FROM warehouse.silver.customer WHERE customer_id IS NULL","validation_comparison_query_sql":null,"validation_result_data_type":"integer","validation_comparison_operator":"equal","validation_comparison_value_type":"literal","validation_comparison_value":0,"is_active":true}]'::jsonb, 60)
) AS seed(workflow, mode, stage_code, name, resolver, data_type, description, example, variable_order)
JOIN application.workflow_stage AS stage
  ON stage.project_workflow = seed.workflow
 AND stage.workflow_execution_mode IS NOT DISTINCT FROM seed.mode
 AND stage.workflow_stage_code = seed.stage_code
 AND stage.workflow_stage_is_agentic
ORDER BY stage.workflow_stage_id, seed.variable_order
    LOOP
        SELECT * INTO existing_row
          FROM application.workflow_stage_variable
         WHERE workflow_stage_id = seed_row.workflow_stage_id
           AND workflow_stage_variable_name = seed_row.name
         FOR UPDATE;
        IF FOUND THEN
            IF existing_row.workflow_stage_variable_resolver_key IS DISTINCT FROM seed_row.resolver
               OR existing_row.workflow_stage_variable_data_type IS DISTINCT FROM seed_row.data_type THEN
                RAISE EXCEPTION 'Reference variable identity conflicts with an existing definition';
            END IF;
            UPDATE application.workflow_stage_variable
               SET workflow_stage_variable_description = seed_row.description,
                   workflow_stage_variable_example = seed_row.example
             WHERE workflow_stage_variable_id = existing_row.workflow_stage_variable_id
               AND (workflow_stage_variable_description IS DISTINCT FROM seed_row.description
                    OR workflow_stage_variable_example IS DISTINCT FROM seed_row.example);
        ELSE
            SELECT COALESCE(MAX(workflow_stage_variable_order), 0) + 10
              INTO next_order
              FROM application.workflow_stage_variable
             WHERE workflow_stage_id = seed_row.workflow_stage_id;
            INSERT INTO application.workflow_stage_variable (
                workflow_stage_id, workflow_stage_variable_name,
                workflow_stage_variable_resolver_key, workflow_stage_variable_data_type,
                workflow_stage_variable_is_required, workflow_stage_variable_description,
                workflow_stage_variable_example, workflow_stage_variable_order
            ) VALUES (
                seed_row.workflow_stage_id, seed_row.name, seed_row.resolver, seed_row.data_type,
                FALSE, seed_row.description, seed_row.example, next_order
            );
        END IF;
    END LOOP;
END;
$workflow_variable_seed$;
